function mergeAndSink(nums: number[]): number[] {
  const a = [...nums];
  for (let i = 0; i + 1 < a.length; i++) {
    if (a[i] === a[i + 1]) {
      a[i] *= 2;
      a[i + 1] = 0;
    }
  }
  const kept = a.filter(v => v !== 0);
  return kept.concat(new Array(a.length - kept.length).fill(0));
}

