    def mergeAndSink(self, nums: List[int]) -> List[int]:
        a = nums[:]
        for i in range(len(a) - 1):
            if a[i] == a[i + 1]:
                a[i] *= 2
                a[i + 1] = 0
        kept = [v for v in a if v]
        return kept + [0] * (len(a) - len(kept))

