function mergeAndSink(nums: number[]): number[] {
  const n = nums.length;
  let w = 0;
  for (let i = 0; i < n; i++) {
    if (i + 1 < n && nums[i] === nums[i + 1]) {
      nums[i] *= 2;
      nums[i + 1] = 0;
    }
    if (nums[i] !== 0) nums[w++] = nums[i];
  }
  while (w < n) nums[w++] = 0;
  return nums;
}

