class Solution:
    def mergeAndSink(self, nums: List[int]) -> List[int]:
        n, w = len(nums), 0
        for i in range(n):
            if i + 1 < n and nums[i] == nums[i + 1]:
                nums[i] *= 2
                nums[i + 1] = 0
            if nums[i]:
                nums[w] = nums[i]
                w += 1
        for k in range(w, n):
            nums[k] = 0
        return nums

